def get_diamond_perimeter(n):
    flooded = set()
    for x in range(-n-1, n+2):
        for y in range(-n-1, n+2):
            if abs(x) + abs(y) <= n:
                flooded.add((x, y))

    edges = set()
    for x, y in flooded:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in flooded:
                # This is a boundary edge.
                # To avoid double counting, we can represent an edge as a sorted tuple of two cells.
                edge = tuple(sorted([(x, y), (nx, ny)]))
                edges.add(edge)
    return len(edges)

for n in range(10):
    print(f"n={n}, perimeter={get_diamond_perimeter(n)}")

