def get_flooded_perimeter(initial_cells, n):
    flooded = set(initial_cells)
    for _ in range(n):
        new_cells = set()
        for x, y in flooded:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in flooded:
                    new_cells.add((nx, ny))
        flooded.update(new_cells)

    edges = set()
    for x, y in flooded:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in flooded:
                edge = tuple(sorted([(x, y), (nx, ny)]))
                edges.add(edge)
    return len(edges)

