def solve():
    import random

    def simulate(initial_cells, max_n):
        flooded = set(initial_cells)
        boundary = set()
        for x, y in flooded:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                if (x + dx, y + dy) not in flooded:
                    boundary.add((x, y, x + dx, y + dy))

        # Wait, the boundary is a set of edges.
        # Let's store edges as sorted tuples.
        edges = set()
        for x, y in flooded:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if (nx, ny) not in flooded:
                    edges.add(tuple(sorted([(x, y), (nx, ny)])))

        perimeter_history = [len(edges)]

        for n in range(1, max_n):
            new_flooded = set()
            for x, y in flooded:
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = x + dx, y + dy
                    if (nx, ny) not in flooded:
                        new_flooded.add((nx, ny))

            if not new_flooded:
                perimeter_history.append(len(edges))
                continue

            flooded.update(new_flooded)

            # Recompute edges (it's faster than trying to update them carefully)
            # But let's just use the fact that the boundary cells are the new_flooded ones and their neighbors
            edges = set()
            for x, y in flooded:
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = x + dx, y + dy
                    if (nx, ny) not in flooded:
                        edges.add(tuple(sorted([(x, y), (nx, ny)])))
            perimeter_history.append(len(edges))

        return perimeter_history

    for _ in range(5):
        num_initial = random.randint(1, 10)
        initial_cells = []
        for _ in range(num_initial):
            initial_cells.append((random.randint(-20, 20), random.randint(-20, 20)))

        perims = simulate(initial_cells, 50)
        rates = [perims[i+1] - perims[i] for i in range(len(perims)-1)]
        print(f"Num: {num_initial}, Avg rate: {sum(rates[30:])/20}")

